<?php
require __DIR__.'/bootstrap.php';require_auth();if((user()['role_code']??'')!=='main_admin'){http_response_code(403);exit('Only the Main Admin Account can reverse customer payments.');}require __DIR__.'/partials.php';
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$db->prepare('SELECT cp.*,c.name customer,c.outstanding FROM customer_payments cp JOIN customers c ON c.id=cp.customer_id WHERE cp.id=?');$stmt->execute([$id]);$payment=$stmt->fetch();if(!$payment){http_response_code(404);exit('Payment not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=in_array($_POST['reversal_type']??'',['cheque_returned','cash_returned','payment_reversed','other'],true)?$_POST['reversal_type']:'payment_reversed';$reason=trim($_POST['reason']??'');if($reason===''){flash('danger','Enter the reason for returning or reversing this payment.');redirect('customer_payment_reverse.php?id='.$id);}$db->beginTransaction();try{$lock=$db->prepare('SELECT * FROM customer_payments WHERE id=? FOR UPDATE');$lock->execute([$id]);$current=$lock->fetch();if(!$current||$current['status']==='reversed')throw new RuntimeException('This payment has already been reversed.');$alloc=$db->prepare('SELECT sale_id,amount FROM customer_payment_allocations WHERE payment_id=? ORDER BY id FOR UPDATE');$alloc->execute([$id]);$allocations=$alloc->fetchAll();$restored=0;foreach($allocations as $row){$saleStmt=$db->prepare('SELECT * FROM sales WHERE id=? FOR UPDATE');$saleStmt->execute([$row['sale_id']]);$sale=$saleStmt->fetch();if(!$sale)continue;$amount=(float)$row['amount'];$newPaid=max(0,(float)$sale['paid_amount']-$amount);$newBalance=min((float)$sale['total'],(float)$sale['balance']+$amount);$newStatus=$newPaid>0?'partially_paid':((!empty($sale['due_date'])&&$sale['due_date']<date('Y-m-d'))?'overdue':'unpaid');$db->prepare('UPDATE sales SET paid_amount=?,balance=?,status=? WHERE id=?')->execute([$newPaid,$newBalance,$newStatus,$sale['id']]);$restored+=$amount;}$restoreAccount=$restored>0?$restored:(float)$current['amount'];$db->prepare('UPDATE customers SET outstanding=outstanding+?,total_payments=GREATEST(0,total_payments-?) WHERE id=?')->execute([$restoreAccount,(float)$current['amount'],$current['customer_id']]);$db->prepare('UPDATE customer_payments SET status="reversed",reversal_type=?,reversal_reason=?,reversed_at=NOW(),reversed_by=? WHERE id=?')->execute([$type,$reason,user()['id'],$id]);audit($db,'reverse','customer_payment',$id,['status'=>'posted','amount'=>$current['amount']],['status'=>'reversed','type'=>$type,'reason'=>$reason,'restored_customer_balance'=>$restoreAccount]);$db->commit();flash('success','Payment reversed. The invoice and customer balance were reopened.');redirect('customer_view.php?id='.$current['customer_id'].'#ledger');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect('customer_payment_reverse.php?id='.$id);}}
page_start('Return / Reverse Customer Payment','payments.php');?>
<section class="correction-shell"><div class="correction-warning"><b>This reopens the customer debt</b><span>The original receipt remains in history and is marked Reversed.</span></div><section class="panel reversal-summary"><span class="eyebrow">Original receipt</span><h2><?=e($payment['receipt_no'])?></h2><div class="reversal-facts"><p><span>Customer</span><b><?=e($payment['customer'])?></b></p><p><span>Amount</span><b><?=money($payment['amount'])?></b></p><p><span>Method</span><b><?=e(str_replace('_',' ',$payment['method']))?></b></p><p><span>Reference</span><b><?=e($payment['reference_no']?:'-')?></b></p><p><span>Status</span><b><?=e($payment['status'])?></b></p></div></section><?php if($payment['status']==='reversed'):?><div class="alert danger">Already reversed: <?=e($payment['reversal_reason'])?></div><?php else:?><form method="post" class="panel reversal-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><label>What happened?<select name="reversal_type"><option value="cheque_returned">Cheque returned / bounced</option><option value="cash_returned">Cash returned to customer</option><option value="payment_reversed">Payment entered by mistake</option><option value="other">Other reversal</option></select></label><label>Reason and details<textarea name="reason" rows="4" required></textarea></label><div class="reversal-warning"><b>This will reopen debt of up to <?=money($payment['amount'])?>.</b></div><button class="btn danger-action wide" data-confirm="Reverse this payment and reopen the invoice balance?">Confirm Reversal</button><a class="btn secondary wide" href="customer_view.php?id=<?=$payment['customer_id']?>#ledger">Cancel</a></form><?php endif;?></section>
<style>.reversal-summary,.reversal-form{padding:24px;margin-bottom:16px}.reversal-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.reversal-facts p{display:flex;flex-direction:column;gap:4px;background:#f7f9f6;padding:12px;border-radius:8px}.reversal-facts span{font-size:10px;color:#718078;text-transform:uppercase}.reversal-form{display:grid;gap:14px}.reversal-warning{background:#ffe5e2;color:#a63731;padding:13px;border-radius:8px}.danger-action{background:#b43d36;color:#fff}@media(max-width:650px){.reversal-facts{grid-template-columns:1fr}}</style><?php page_end();
